def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    separated_groups = []  # Initialize an empty list to store the separated groups
    start = 0
    end = 0

    while end < len(paren_string):
        if paren_string[end] == '(':
            count = 1
            end += 1
            while count != 0:
                if paren_string[end] == '(':
                    count += 1
                elif paren_string[end] == ')':
                    count -= 1
                end += 1
            separated_groups.append(paren_string[start:end])  # Extract each group using the indices
